import { OFFLINE_MODE_ENABLED } from "./flags";
import { startQueueWorker } from "./queue";
import { ensureFreshSnapshot } from "./snapshot";

/**
 * Registers the Workbox service worker generated by vite-plugin-pwa (only
 * emitted when the build ran with VITE_ENABLE_OFFLINE_MODE=true) and starts
 * the queue worker. main.tsx calls this behind the same flag; the guard is
 * repeated here so an accidental call is still a no-op.
 */
export function registerOfflineServiceWorker(): void {
  if (!OFFLINE_MODE_ENABLED || typeof window === "undefined") return;

  if ("serviceWorker" in navigator) {
    window.addEventListener("load", () => {
      navigator.serviceWorker
        .register("/sw.js", { scope: "/" })
        .then((reg) => {
          // registerType "autoUpdate": the new worker skips waiting + claims
          // clients itself; just make sure we look for it now and then.
          window.setInterval(() => void reg.update().catch(() => undefined), 60 * 60 * 1000);
        })
        .catch((err) => {
          console.warn("[offline] service worker registration failed", err);
        });
    });
  }

  startQueueWorker();
  // Warm the menu cache once we are online and signed in.
  window.addEventListener("online", () => void ensureFreshSnapshot(0));
  void ensureFreshSnapshot();
}
